import{_t as e,it as t,n,rt as r}from"./chunks/framework.Ke88N3OB.js";var i=JSON.parse(`{"title":"@pumpkin-plugins/plugin-kit","description":"","frontmatter":{"editLink":"https://github.com/filiphsps/pumpkin-plugins/edit/master/tools/plugin-kit/README.md"},"headers":[],"relativePath":"tools/plugin-kit/README.md","filePath":"tools/plugin-kit/README.md","lastUpdated":1792252051000}`),a={name:`tools/plugin-kit/README.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="pumpkin-plugins-plugin-kit" tabindex="-1">@pumpkin-plugins/plugin-kit <a class="header-anchor" href="#pumpkin-plugins-plugin-kit" aria-label="Permalink to “@pumpkin-plugins/plugin-kit”">​</a></h1><p><a href="https://www.npmjs.com/package/@pumpkin-plugins/plugin-kit" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/dt/%40pumpkin-plugins%2Fplugin-kit" alt="npm downloads"></a><a href="https://www.npmjs.com/package/@pumpkin-plugins/plugin-kit" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/v/%40pumpkin-plugins%2Fplugin-kit?label=latest%20release" alt="latest npm release"></a><a href="https://www.npmjs.com/package/@pumpkin-plugins/plugin-kit" target="_blank" rel="noreferrer"><img src="https://img.shields.io/npm/l/%40pumpkin-plugins%2Fplugin-kit" alt="npm license"></a></p><p>Shared building blocks for plugins: a common plugin base and registration wrapper, data folders, logging, scheduled tasks, command registration, plugin messages and binary payload encoders, plus in-memory fakes for tests. <code>PluginBase</code> derives Pumpkin metadata from <code>src/info.ts</code>, runs common lifecycle behavior, and <code>registerPlugin</code> starts the non-blocking Market update check after loading. Plugin entry points export <code>handleTask</code> from the shared plugin module to dispatch the check&#39;s polling tasks.</p><p>The scheduling helpers accept whole, nonnegative tick counts; repeating periods must be at least one tick. <code>cancelTask</code> cancels either delayed or repeating tasks and releases their callbacks. Delayed callbacks are also released before they run, and failed scheduling retains no callback.</p><p>Use <code>ansi.named</code> from <code>@pumpkin-plugins/minecraft-colors</code> for log values worth scanning, such as names, filenames, URLs, versions, UUIDs and ports. Pick the named role that fits the value and keep the surrounding message plain. The <code>color.named</code> formatter emits Minecraft codes for chat replies. See the <a href="/pumpkin-plugins/guides/code-style#color-in-console-logs">console color convention</a> for the palette source.</p><p><code>WasiDataDir.writeFile</code> replaces files through an exclusively created temporary sibling. Failed writes and renames clean up that sibling without replacing the original error. Directory creation checks that existing entries are directories; removing a symlink removes the link itself. Random-access file handles reject invalid read ranges and can be closed more than once.</p><p>The <code>MemoryFiles</code> test fake copies bytes at its boundaries, rejects file/directory conflicts and nonempty directory removal, and enforces file-handle closure. Use <code>put</code> to seed fixtures with missing parents; <code>writeFile</code> requires its parent directory to exist, matching the WASI adapter.</p><p>For shared coding conventions, see the <a href="/pumpkin-plugins/guides/code-style">code style guide</a>.</p><p>See the <a href="https://filiphsps.github.io/pumpkin-plugins/tools/plugin-kit/docs/" target="_blank" rel="noreferrer">tool guide</a> and <a href="https://filiphsps.github.io/pumpkin-plugins/api/tools/@pumpkin-plugins/plugin-kit/" target="_blank" rel="noreferrer">API reference</a> on the documentation site.</p>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};